// Allowlist normalization, secret comparison, and identity minting for one
// GoHighLevel outbound-webhook delivery.
//
// This node performs no writes and must never throw. A malformed or hostile
// body has to reach the 401 / 422 branches, not crash the execution into a
// 500 that GHL would then retry.

const body = $input.first().json.body ?? {};

// GHL nests the declared Custom Data under a `customData` object. The vendor
// doc example shows these keys flattened to the root; that is wrong, and
// building against it cost six diagnostic deliveries on 2026-08-09. Read the
// nested object, fall back to the root, so the workflow survives either shape
// rather than depending on which one the vendor ships.
const cd = (body.customData && typeof body.customData === 'object')
  ? body.customData
  : body;

const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();

// GHL's free Outbound Webhook action supports no custom headers and no
// signature, so the shared secret travels in the body. It is compared here,
// before any write of any kind.
const expected = str($vars.GHL_WEBHOOK_SHARED_SECRET);
const provided = str(cd.sharedSecret);

// Fail closed: an unset variable must never authorize a request.
const secretConfigured = expected.length > 0;
const authorized = secretConfigured && provided === expected;

const opportunityId = str(cd.opportunityId);
const contactId = str(cd.contactId);
const email = str(cd.email);
const phone = str(cd.phone);

// opportunityId is required twice over: for the backup row, and because the
// entire delivery identity is derived from it.
const required = { opportunityId, contactId };
const missing = Object.keys(required).filter((k) => required[k] === '');

// A lead has to be reachable. It does not have to be reachable by email.
// Until P08 this node required `email` outright, which rejected a phone-only
// lead the business could simply have called back -- the one outcome
// architecture.md 7 says must never happen, since its invariant is that a
// lead stays CONTACTABLE. Either channel satisfies that; neither does not.
// The pseudo-field name is deliberate: the 422 body then names the rule that
// was broken instead of arbitrarily blaming one of the two fields.
if (email === '' && phone === '') {
  missing.push('email_or_phone');
}

return [{
  json: {
    authorized,

    // Distinguishes 'the n8n variable is missing or misnamed' from 'the two
    // secrets simply differ'. Both produce a 401, and without this they are
    // indistinguishable from outside.
    //
    // This replaces a diagnostic object that also emitted the expected and
    // provided secret LENGTHS. Those travelled in every item and were
    // persisted in execution data. A boolean answers the same question and
    // discloses nothing about the secret itself.
    secretConfigured,

    valid: missing.length === 0,
    missingFields: missing.join(','),

    // Stable per event. Derived, never sent by GHL. Consistent with ADR-002,
    // this exists only once GHL has already created the Opportunity, so it
    // dedupes deliveries and must never gate whether the Opportunity is made.
    eventId: opportunityId ? ('ghl:opportunity-created:' + opportunityId) : '',

    // New per delivery. A redelivery is a new execution, so this changes --
    // which is exactly what makes a duplicate legible in run_log.
    correlationId: 'n8n:' + $execution.id,

    timestamp: new Date().toISOString(),

    contactId,
    opportunityId,
    name: str(cd.name),
    email,
    phone,
    business: str(cd.business),
    service: str(cd.service),
    source: str(cd.source),
    stage: str(cd.stage),
    appointment: '',
    lastAction: 'webhook_received'
  }
}];

// Merge the ledger lookup back onto the normalized delivery.
//
// The Data Table node emits the ledger row, not our payload, so the
// normalized fields are pulled back by node reference rather than threaded
// through the item.

const norm = $('Normalize and Authorize').first().json;

// With Always Output Data on, a miss produces one empty-ish item. Only a row
// that actually carries our eventId counts as a hit.
const existing = $input.all()
  .map((i) => i.json)
  .find((r) => r && r.eventId === norm.eventId) ?? null;

const prevAttempt = Number(existing?.attempt);

return [{
  json: {
    ...norm,
    ledgerFound: existing !== null,
    ledgerStatus: existing?.status ?? '',

    // Only 'completed' short-circuits. A stale 'claimed' -- a delivery that
    // died between the backup write and the ledger update -- deliberately
    // proceeds, because the leads_backup write is keyed on eventId and is
    // therefore safe to repeat. See ADR-002 'the race window, honestly'.
    alreadyProcessed: existing?.status === 'completed',

    attempt: (Number.isFinite(prevAttempt) ? prevAttempt : 0) + 1,
    firstSeenAt: existing?.firstSeenAt || norm.timestamp
  }
}];

// Operator-only fault injection, for TC-10 / TC-11 / TC-12.
//
// The switch is a row in the `leadflow_test_controls` Data Table, which only
// somebody with n8n access can write. It is deliberately NOT a payload field:
// letting the public form decide whether the pipeline fails would hand an
// anonymous submitter both a denial-of-service lever and a way to push chosen
// leads into the human-review queue.
//
// The table is append-only, so flipping the switch means appending a new row
// rather than editing the old one, and the highest id wins. That began as a
// constraint -- n8n exposes no row update -- and turned out better than a
// mutable flag: the switch carries its own history, so 'who armed this, when,
// and why' is answerable after the fact. The cost is a table that only grows.
//
// Fail-open by construction. A missing row, an unreadable table, or a value
// this node does not recognise all mean 'off'. A broken test switch must
// never be able to take production down.
const ctx = $('Ledger State').first().json;

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.key === 'backup_fault')
  .sort((a, b) => Number(b.id ?? 0) - Number(a.id ?? 0));

const row = rows[0];

const mode = String(row?.mode ?? 'off').trim().toLowerCase();
const scope = String(row?.eventScope ?? '').trim();

// Scope is a PREFIX of the opportunityId, not a substring of the eventId.
//
// It was a substring match until an adversarial review pointed out that
// opportunityId arrives verbatim from the payload, so a caller who held the
// shared secret and knew the armed scope could embed it anywhere in an id and
// steer a chosen lead into the human-review queue. A prefix match on the id
// alone is narrower, and matches how the scope is actually documented.
//
// An empty scope still arms every delivery, which is why production is left
// with mode=off rather than relying on scope to be set.
const opportunityId = String(ctx.opportunityId ?? '');
const inScope = scope === '' || opportunityId.startsWith(scope);

if (mode === 'always' && inScope) {
  throw new Error('injected downstream failure (leadflow_test_controls.backup_fault=always, scope="' + scope + '")');
}

return [{ json: ctx, pairedItem: { item: 0 } }];

// Decide what happens after a failed attempt at the durable backup write.
//
// This node is the entire retry policy, in one place and on purpose: the four
// constants below ARE the budget, and nothing else in the workflow gets an
// opinion about them.
//
//   maxAttempts  3     one first attempt plus two retries
//   base         70s
//   factor       2     70s then 140s -- exhausted after roughly 3.5 minutes
//   jitter       additive only, 0-20%
//   cap          300s
//
// The jitter is additive-only deliberately. n8n keeps a Wait of under 65
// seconds in memory and only persists longer ones to the database, so a
// subtractive jitter could push the first retry under that line and make
// durability depend on a coin flip. Every wait scheduled here is at least 70
// seconds and therefore survives a restart of the instance.
const MAX_ATTEMPTS = 3;
const BASE_SECONDS = 70;
const FACTOR = 2;
const CAP_SECONDS = 300;

// $runIndex counts this node's own executions inside the run, so it is the
// retry counter: 0 the first time the write failed, 1 the second, and so on.
const attemptNumber = $runIndex + 1;
const exhausted = attemptNumber >= MAX_ATTEMPTS;

const ctx = $('Ledger State').first().json;

const raw = $input.first().json ?? {};
const errText = String(
  raw.error?.message ?? raw.error ?? 'unknown downstream failure'
).slice(0, 300);

let delaySeconds = 0;
let nextAttemptAt = '';

if (!exhausted) {
  const base = Math.min(CAP_SECONDS, BASE_SECONDS * Math.pow(FACTOR, attemptNumber - 1));
  delaySeconds = Math.round(base * (1 + Math.random() * 0.2));
  nextAttemptAt = new Date(Date.now() + delaySeconds * 1000).toISOString();
}

const progress = `attempt ${attemptNumber}/${MAX_ATTEMPTS}`;

return [{
  json: {
    ...ctx,
    backupAttempt: attemptNumber,
    maxAttempts: MAX_ATTEMPTS,
    exhausted,

    // Whether the caller is still waiting. Only the first failure of a
    // delivery still owes GHL an HTTP response; by the second the connection
    // has already been answered 202, and answering it twice crashes the run.
    firstFailure: attemptNumber === 1,

    delaySeconds,
    nextAttemptAt,
    lastError: errText,
    ledgerStatusNext: exhausted ? 'failed' : 'retry_scheduled',
    runLogStatus: exhausted ? 'failed' : 'retrying',
    runLogOutcome: exhausted ? 'retry_exhausted' : 'retry_scheduled',
    runLogError: exhausted
      ? `backup write failed, ${progress}, retry budget exhausted: ${errText}`
      : `backup write failed, ${progress}, next attempt at ${nextAttemptAt}: ${errText}`
  },
  pairedItem: { item: 0 }
}];
